import Foundation
import Testing
@testable import RHCrypto

/// contracts/vectors/jcs.json, generated by RHServer. The client must pass scope "protocol".
private struct JCSVector: Decodable {
    let name: String
    let input: String
    let expected: String
    let expected_sha256: String
    let scope: String
}

struct JCSVectorTests {
    @Test func protocolScopeVectors() throws {
        let vectors = try JSONDecoder()
            .decode([JCSVector].self, from: ContractsLocation.data("vectors/jcs.json"))
            .filter { $0.scope == "protocol" }
        #expect(!vectors.isEmpty, "no protocol-scope vectors in contracts/vectors/jcs.json")
        for vector in vectors {
            let canonical = try JCS.canonicalize(jsonText: vector.input)
            #expect(canonical == Array(vector.expected.utf8), "\(vector.name): canonical bytes differ")
            #expect(sha256Hex(canonical) == vector.expected_sha256, "\(vector.name): sha256 differs")
        }
    }
}
